{"command":"cat <<'EOF' > test_regex.go
package main

import (
	"fmt"
	"regexp"
)

func formatJSON(s string) string {
	// Key
	s = regexp.MustCompile(`"([^"]+)":`).ReplaceAllString(s, `"\x1b[95m$1\x1b[0m":`)

	// String value
	s = regexp.MustCompile(`:\s+"([^"]+)"`).ReplaceAllString(s, `: "\x1b[96m$1\x1b[0m"`)

	// Value (number/bool/null) at the end of object (forgot reset!)
	s = regexp.MustCompile(`([a-zA-Z0-9\.-]+)(\s*\})`).ReplaceAllString(s, `\x1b[96m$1$2`)

	// Value with comma
	s = regexp.MustCompile(`:\s+([a-zA-Z0-9\.-]+)`).ReplaceAllString(s, `: \x1b[96m$1\x1b[0m`)

	// First item in array
	s = regexp.MustCompile(`(\[\s*)([a-zA-Z0-9\.-]+)`).ReplaceAllString(s, `$1\x1b[96m$2\x1b[0m`)

	// Array item at the end of array (forgot reset!)
	s = regexp.MustCompile(`([a-zA-Z0-9\.-]+)(\s*\])`).ReplaceAllString(s, `\x1b[95m$1$2`)

	// Other items in array
	s = regexp.MustCompile(`(,\s*)([a-zA-Z0-9\.-]+)`).ReplaceAllString(s, `$1\x1b[95m$2\x1b[0m`)

	// String in array
	s = regexp.MustCompile(`(\[\s*|,\s*)"([^"]+)"`).ReplaceAllString(s, `$1"\x1b[95m$2\x1b[0m"`)

	return s
}

func main() {
	input := "{\n  \"i\": [\n    true,\n    1\n  ]\n}\n"
	fmt.Printf("%q\n", formatJSON(input))
}
EOF
go run test_regex.go"}

