{"command":"cat <<'EOF' > test_formatter.go
package main

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

func formatJSON(b []byte) string {
	var prettyJSON strings.Builder
	if err := json.Indent(&prettyJSON, b, "", "  "); err != nil {
		return string(b)
	}
	s := prettyJSON.String()

	// Keys: "key":
	s = regexp.MustCompile(`"([^"]+)":`).ReplaceAllString(s, `"\x1b[95m$1\x1b[0m":`)

	// Values: : "value" (with comma)
	s = regexp.MustCompile(`:\s+"([^"]+)",`).ReplaceAllString(s, `: "\x1b[96m$1\x1b[0m",`)
	// Values: : "value" (without comma)
	s = regexp.MustCompile(`:\s+"([^"]+)"\n`).ReplaceAllString(s, `: "\x1b[96m$1\x1b[0m"\n`)

	// Values: : 123 (with comma)
	s = regexp.MustCompile(`:\s+([a-zA-Z0-9\.-]+),`).ReplaceAllString(s, `: \x1b[96m$1\x1b[0m,`)
	// Values: : 123 (without comma) -> BUG: missing \x1b[0m
	s = regexp.MustCompile(`:\s+([a-zA-Z0-9\.-]+)\n`).ReplaceAllString(s, `: \x1b[96m$1\n`)

	// Arrays First String (with comma)
	s = regexp.MustCompile(`\[\n(\s+)"([^"]+)",`).ReplaceAllString(s, `[\n$1"\x1b[96m$2\x1b[0m",`)
	// Arrays First String (without comma)
	s = regexp.MustCompile(`\[\n(\s+)"([^"]+)"\n`).ReplaceAllString(s, `[\n$1"\x1b[96m$2\x1b[0m"\n`)

	// Arrays First Num (with comma)
	s = regexp.MustCompile(`\[\n(\s+)([a-zA-Z0-9\.-]+),`).ReplaceAllString(s, `[\n$1\x1b[96m$2\x1b[0m,`)
	// Arrays First Num (without comma) -> BUG: missing \x1b[0m
	s = regexp.MustCompile(`\[\n(\s+)([a-zA-Z0-9\.-]+)\n`).ReplaceAllString(s, `[\n$1\x1b[96m$2\n`)

	// Arrays Middle String (with comma)
	s = regexp.MustCompile(`,\n(\s+)"([^"]+)",`).ReplaceAllString(s, `,\n$1"\x1b[95m$2\x1b[0m",`)
	// Arrays Last String (without comma)
	s = regexp.MustCompile(`,\n(\s+)"([^"]+)"\n`).ReplaceAllString(s, `,\n$1"\x1b[95m$2\x1b[0m"\n`)

	// Arrays Middle Num (with comma)
	s = regexp.MustCompile(`,\n(\s+)([a-zA-Z0-9\.-]+),`).ReplaceAllString(s, `,\n$1\x1b[95m$2\x1b[0m,`)
	// Arrays Last Num (without comma) -> BUG: missing \x1b[0m
	s = regexp.MustCompile(`,\n(\s+)([a-zA-Z0-9\.-]+)\n`).ReplaceAllString(s, `,\n$1\x1b[95m$2\n`)

	return s
}

func main() {
	input := `{"i": ["hello", "world"]}`
	fmt.Printf("%q\n", formatJSON([]byte(input)))

	input2 := `{"i": [123]}`
	fmt.Printf("%q\n", formatJSON([]byte(input2)))

	input3 := `{"c": -5}`
	fmt.Printf("%q\n", formatJSON([]byte(input3)))
}
EOF
go run test_formatter.go"}

