{"command":"cat <<'EOF' > test_dump.go
package main

import (
	"bytes"
	"fmt"
	"net/http"
	"net/http/httputil"
	"regexp"
)

func formatHeader(s string) string {
	// Request line
	s = regexp.MustCompile(`^(GET|POST|PUT|DELETE|OPTIONS|HEAD|PATCH)`).ReplaceAllString(s, "\x1b[95m$1\x1b[0m")
	s = regexp.MustCompile(` (/[^ ]*) `).ReplaceAllString(s, " \x1b[96m$1\x1b[0m ")
	s = regexp.MustCompile(`(HTTP/[\d\.]+\r)\n`).ReplaceAllString(s, "\x1b[95m$1\x1b[0m\n")

	// Headers
	s = regexp.MustCompile(`([a-zA-Z0-9-]+):(.*)\r\n`).ReplaceAllString(s, "\x1b[90m$1\x1b[0m:\x1b[96m$2\r\x1b[0m\n")

	return s
}

func main() {
	req, _ := http.NewRequest("POST", "http://localhost:8083/abc", bytes.NewBufferString(`{"name":"John"}`))
	req.Header.Set("Host", "localhost:8083")
	req.Header.Set("Accept", "application/json")

	dump, _ := httputil.DumpRequest(req, false)
	fmt.Printf("%q\n", formatHeader(string(dump)))
}
EOF
go run test_dump.go"}

