	s = regexp.MustCompile(`\[\n(\s+)"([^"]+)"\n`).ReplaceAllString(s, "[\n$1\"\x1b[96m$2\x1b[0m\"\n")
	s = regexp.MustCompile(`\[\n(\s+)([a-zA-Z0-9\.-]+),`).ReplaceAllString(s, "[\n$1\x1b[96m$2\x1b[0m,")
	s = regexp.MustCompile(`\[\n(\s+)([a-zA-Z0-9\.-]+)\n`).ReplaceAllString(s, "[\n$1\x1b[96m$2\n")
	s = regexp.MustCompile(`,\n(\s+)"([^"]+)",`).ReplaceAllString(s, ",\n$1\"\x1b[95m$2\x1b[0m\",")
	s = regexp.MustCompile(`,\n(\s+)"([^"]+)"\n`).ReplaceAllString(s, ",\n$1\"\x1b[95m$2\x1b[0m\"\n")
	s = regexp.MustCompile(`,\n(\s+)([a-zA-Z0-9\.-]+),`).ReplaceAllString(s, ",\n$1\x1b[95m$2\x1b[0m,")
	s = regexp.MustCompile(`,\n(\s+)([a-zA-Z0-9\.-]+)\n`).ReplaceAllString(s, ",\n$1\x1b[95m$2\n")
	return s
}

func main() {
	flag.Usage = func() {
		fmt.Fprint(os.Stderr, `bat is a Go implemented CLI cURL-like tool for humans.

Usage:

	bat [flags] [METHOD] URL [ITEM [ITEM]]

flags:
  -a, -auth=USER[:PASS]       Pass a username:password pair as the argument
  -b, -bench=false            Sends bench requests to URL
  -b.N=1000                   Number of requests to run
  -b.C=100                    Number of requests to run concurrently
  -body=""                    Send RAW data as body
  -f, -form=false             Submitting the data as a form
  -j, -json=true              Send the data in a JSON object
  -p, -pretty=true            Print Json Pretty Format
  -i, -insecure=false         Allow connections to SSL sites without certs
  -proxy=PROXY_URL            Proxy with host and port
  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat
`)
	}
	flag.Parse()

	if *v || *version {
		fmt.Println("Version: 0.1.0")
		os.Exit(2)
	}

	args := flag.Args()
	if len(args) == 0 {
		return
	}

	method := "GET"
	urlStr := ""
	var items []string

	methods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true, "PATCH": true, "OPTIONS": true, "HEAD": true,
	}

	if methods[strings.ToUpper(args[0])] {
		method = strings.ToUpper(args[0])
		if len(args) > 1 {
			urlStr = args[1]
			items = args[2:]
		}
	} else {
		urlStr = args[0]
		items = args[1:]
	}

	if !strings.Contains(urlStr, "://") {
		urlStr = "http://" + urlStr
	}

	var reqBody []byte
	headers := make(http.Header)
	queries := url.Values{}
	postData := make(map[string]interface{})
	formData := url.Values{}
	hasData := false

	for _, item := range items {
		if strings.Contains(item, ":") {
			parts := strings.SplitN(item, ":", 2)
			headers.Add(parts[0], parts[1])
		} else if strings.Contains(item, "=") {
			hasData = true
			parts := strings.SplitN(item, "=", 2)
			if method == "GET" {
				queries.Add(parts[0], parts[1])
			} else {
				postData[parts[0]] = parts[1]
				formData.Add(parts[0], parts[1])
			}
		}
	}

	if *bodyArg != "" {
		hasData = true
		reqBody = []byte(*bodyArg)
	} else if method != "GET" && hasData {
		if *form || *formLong {
			reqBody = []byte(formData.Encode())
			headers.Set("Content-Type", "application/x-www-form-urlencoded")
		} else if *jsonFlag || *jsonLong {
			b, _ := json.Marshal(postData)
			reqBody = b
			headers.Set("Content-Type", "application/json")
		}
	}

	if method == "GET" && hasData && len(queries) > 0 {
		u, _ := url.Parse(urlStr)
		q := u.Query()
		for k, v := range queries {
			for _, v2 := range v {
				q.Add(k, v2)
			}
		}
		u.RawQuery = q.Encode()
		urlStr = u.String()
	}

	if method == "GET" && (hasData || *bodyArg != "") && !methods[strings.ToUpper(args[0])] {
		method = "POST"
	}

	req, err := http.NewRequest(method, urlStr, bytes.NewReader(reqBody))
	if err != nil {
		log.Fatal(err)
	}

	req.Header.Set("User-Agent", "bat/0.1.0")
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Accept-Encoding", "gzip, deflate")

	for k, v := range headers {
		for _, v2 := range v {
			req.Header.Set(k, v2)
		}
	}

	a := *auth
	if *authLong != "" {
		a = *authLong
	}
	if a != "" {
		parts := strings.SplitN(a, ":", 2)
		if len(parts) == 2 {
			req.SetBasicAuth(parts[0], parts[1])
		} else {
			req.SetBasicAuth(parts[0], "")
		}
	}

	client := &http.Client{
		Timeout: 30 * time.Second,
	}
	transport := &http.Transport{}

	if *insecure || *insecureLong {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if *proxy != "" {
		if !strings.Contains(*proxy, "://") {
			*proxy = "http://" + *proxy
		}
		proxyURL, _ := url.Parse(*proxy)
		if proxyURL != nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	}
	client.Transport = transport

	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("can't get the url %s %q: %v", strings.Title(strings.ToLower(method)), urlStr, err)
	}
	defer resp.Body.Close()

	resBody, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}

	if !isTerminal() {
		fmt.Println("")
		if (*pretty || *prettyLong) && strings.Contains(strings.ToLower(resp.Header.Get("Content-Type")), "json") {
			var out bytes.Buffer
			if err := json.Indent(&out, resBody, "", "  "); err != nil {
				log.Printf("Response Json Indent: %v", err)
				return
			}
			fmt.Print(out.String())
			return
		}
		fmt.Print(string(resBody))
		return
	}

	reqDump, _ := httputil.DumpRequest(req, false)
	resDump, _ := httputil.DumpResponse(resp, false)

	reqDumpStr := strings.TrimRight(string(reqDump), "\r\n")
	resDumpStr := strings.TrimRight(string(resDump), "\r\n")

	pFlags := *printFlag

	if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "H") {
		fmt.Println(formatReqHeader(reqDumpStr))
	}
	if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "B") {
		if len(reqBody) > 0 {
			if strings.Contains(pFlags, "H") || strings.Contains(pFlags, "A") {
				fmt.Println("\n\n")
			}
			if strings.Contains(req.Header.Get("Content-Type"), "json") {
				fmt.Println(formatJSONStr(reqBody))
			} else {
				fmt.Println(string(reqBody))
			}
		}
	}

	if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "h") {
		if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "H") || strings.Contains(pFlags, "B") {
			fmt.Println("\n")
		}
		fmt.Println(formatResHeader(resDumpStr))
	}

	if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "b") {
		if strings.Contains(pFlags, "A") || strings.Contains(pFlags, "h") {
			fmt.Println("\n")
		}
		if (*pretty || *prettyLong) && strings.Contains(strings.ToLower(resp.Header.Get("Content-Type")), "json") {
			var out bytes.Buffer
			if err := json.Indent(&out, resBody, "", "  "); err != nil {
				log.Printf("Response Json Indent: %v", err)
			} else {
				fmt.Print(formatJSONStr(out.Bytes()))
			}
		} else {
			fmt.Print(string(resBody))
		}
	}
}
EOF
go build -o executable main.go"}
